#define P4KB_KIND_CTRL 2
#define P4KB_KIND_CBM 3
#define P4KB_KIND_SHIFTLOCK 4
#define P4KB_KIND_RESTORE 5

// x, y, w, h: the key's touch area inside the keyboard picture
// dc00, dc01: the key's place in the C64 keyboard matrix (0xff = none)
// mods: modifier the key brings with it (1 = SHIFT)
struct P4Key {
  int16_t x, y, w, h;
  uint8_t dc00, dc01, mods, kind;
  const char *name;
};

